explicit Program(const GlApi& gl) noexcept;
~Program() noexcept;
bool link(GLuint vertex, GLuint fragment);
GLuint name() const noexcept;
const std::string& diagnostic() const noexcept;
void reset() noexcept;

GLuint (STUDY_GL_CALL* CreateProgram)() = nullptr;
void (STUDY_GL_CALL* AttachShader)(GLuint, GLuint) = nullptr;
void (STUDY_GL_CALL* LinkProgram)(GLuint) = nullptr;
void (STUDY_GL_CALL* GetProgramiv)(GLuint, GLenum, GLint*) = nullptr;
void (STUDY_GL_CALL* GetProgramInfoLog)(GLuint, GLsizei, GLsizei*, GLchar*) = nullptr;
void (STUDY_GL_CALL* DetachShader)(GLuint, GLuint) = nullptr;
void (STUDY_GL_CALL* DeleteProgram)(GLuint) = nullptr;
void (STUDY_GL_CALL* UseProgram)(GLuint) = nullptr;

name_ = gl_.CreateProgram();
if (!api_stage(gl_, diagnostic_, "glCreateProgram")) {
    reset();
    return false;
}
if (name_ == 0) {
    diagnostic_ = "API failure: glCreateProgram returned 0";
    return false;
}
gl_.AttachShader(name_, vertex);
if (!api_stage(gl_, diagnostic_, "glAttachShader(vertex)")) {
    reset();
    return false;
}
gl_.AttachShader(name_, fragment);
if (!api_stage(gl_, diagnostic_, "glAttachShader(fragment)")) {
    reset();
    return false;
}
gl_.LinkProgram(name_);
if (!api_stage(gl_, diagnostic_, "glLinkProgram")) {
    reset();
    return false;
}

GLint status = 0;
gl_.GetProgramiv(name_, LinkStatus, &status);
if (!api_stage(gl_, diagnostic_, "glGetProgramiv(GL_LINK_STATUS)")) {
    reset();
    return false;
}

std::vector<GLchar> buffer(static_cast<std::size_t>(log_length), '\0');
GLsizei written = 0;
gl_.GetProgramInfoLog(name_, log_length, &written, buffer.data());
if (!api_stage(gl_, diagnostic_, "glGetProgramInfoLog")) {
    reset();
    return false;
}
if (written < 0 || written >= log_length) {
    diagnostic_ = "API failure: invalid program log length";
    reset();
    return false;
}
log.assign(buffer.data(), static_cast<std::size_t>(written));

gl_.DetachShader(name_, vertex);
if (!api_stage(gl_, diagnostic_, "glDetachShader(vertex)")) {
    reset();
    return false;
}
gl_.DetachShader(name_, fragment);
if (!api_stage(gl_, diagnostic_, "glDetachShader(fragment)")) {
    reset();
    return false;
}

void Program::reset() noexcept {
    if (name_ != 0) {
        gl_.DeleteProgram(name_);
        name_ = 0;
    }
}

study_gl::Program program(gl);
{
    study_gl::Shader vertex(gl), fragment(gl);
    if (!vertex.compile(study_gl::VertexShader, study_shader::vertex)) return 1;
    if (!fragment.compile(study_gl::FragmentShader, study_shader::fragment)) return 1;
    if (!program.link(vertex.name(), fragment.name())) return 1;
} // Shader 정리. program의 링크 결과는 남는다.
